package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContactRepository.Access;
import cn.mop.domain.contact.ContactImportRepository.*;
import cn.mop.domain.contact.ContactImportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
/** Real approved PG/OIDC identities only; targeted claims never consume unrelated jobs. Own created contacts archived. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresContactImportIntegrationTest {
    static final String A="55000000-0000-4000-8000-000000000001",B="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresCustomerContactRepository contacts;static PostgresContactImportRepository imports;static String admin,tadmin,reviewer,msp,viewer;
    final List<String> owned=Collections.synchronizedList(new ArrayList<>());
    @BeforeAll static void setup()throws Exception{String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(8);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);contacts=new PostgresCustomerContactRepository(pool,platform);imports=new PostgresContactImportRepository(pool,platform);admin=actor("padmin",null);reviewer=actor("padmin",admin);tadmin=actor("tadmin",null);msp=actor("msp",null);viewer=actor("viewer",null);assertEquals(List.of(),imports.readinessProblems());baseline(A);baseline(B);}
    static String actor(String role,String except)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT m.user_id::text FROM public.mop_membership m JOIN public.mop_user u ON u.id=m.user_id WHERE m.tenant_id=?::uuid AND m.role_code=? AND m.active AND u.active"+(except==null?"":" AND m.user_id<>?::uuid")+" ORDER BY m.user_id LIMIT 1")){s.setString(1,A);s.setString(2,role);if(except!=null)s.setString(3,except);try(var r=s.executeQuery()){assertTrue(r.next());return r.getString(1);}}}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Access admin(){return access(admin,B);}
    static CustomerContact row(String suffix){return new CustomerContact("SYNTHETIC_IMPORT_"+suffix,Set.of(CustomerContact.Role.REPORTER),null,"synthetic@example.test",null,null,null,true);}
    static Object command(Access a,String route,String key,String hash,Supplier<Object> action){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->imports.authorizeAcceptance(a),action);}
    static void baseline(String tenant){Access a=access(admin,tenant);platform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/customer-contacts/baseline","owned-contact-baseline-v1","a".repeat(64),a.permissionVersion(),()->contacts.authorizeWrite(a,null),()->contacts.create(a,0,new CustomerContact("SYNTHETIC_CONTACT_REPOSITORY_BASELINE",Set.of(CustomerContact.Role.DECISION_MAKER),null,null,null,null,null,true)));}
    Job accept(Access a,List<CustomerContact> rows){byte[] bytes=ContactImportPayloadCodec.encode(rows);Job job=(Job)command(a,"POST /integration/contact-imports",UUID.randomUUID().toString(),ContactImportPayloadCodec.hash(bytes),()->imports.accept(a,rows));owned.add(job.id());return job;}
    Job accept(CustomerContact... rows){return accept(admin(),Arrays.asList(rows));}
    Claim claim(Job job){return imports.claim(job.id(),"test-worker",Duration.ofSeconds(30)).orElseThrow();}
    static JsonNode json(Object v){try{return mapper.readTree(mapper.writeValueAsBytes(v));}catch(Exception failure){throw new IllegalStateException(failure);}}
    static long count(String sql)throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery(sql)){assertTrue(r.next());return r.getLong(1);}}
    static String scalar(String sql)throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery(sql)){assertTrue(r.next());return r.getString(1);}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    @AfterEach void completeOnlyOwnedJobsAndArchiveOwnRows()throws Exception{for(String id:owned){long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(45);while(!Set.of("SUCCEEDED","FAILED").contains(scalar("SELECT state FROM public.mop_contact_import_job WHERE id='"+id+"'"))){assertTrue(System.nanoTime()<deadline,"Owned job cleanup did not reach terminal state");String state=scalar("SELECT state FROM public.mop_contact_import_job WHERE id='"+id+"'");if(state.equals("LEASED")){String worker=scalar("SELECT lease_owner FROM public.mop_contact_import_job WHERE id='"+id+"'");long fence=count("SELECT fencing_token FROM public.mop_contact_import_job WHERE id='"+id+"'");imports.process(new Claim(id,worker,fence));}var next=imports.claim(id,"owned-cleanup",Duration.ofSeconds(30));if(next.isPresent())imports.process(next.get());else Thread.sleep(20);}String tenant=scalar("SELECT tenant_id::text FROM public.mop_contact_import_job WHERE id='"+id+"'");List<String> ids=new ArrayList<>();try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT contact_id::text FROM public.mop_contact_import_result WHERE job_id='"+id+"' ORDER BY row_number")){while(r.next())ids.add(r.getString(1));}for(String contact:ids){Access a=access(admin,tenant);var current=contacts.get(a,contact);assertTrue(current.facts().name().startsWith("SYNTHETIC_"));if(!current.archived())platform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/import-cleanup/"+contact,UUID.randomUUID().toString(),"d".repeat(64),a.permissionVersion(),()->contacts.authorizeWrite(a,contact),()->contacts.archive(a,contact,current.version()));}}}
    @Test void acceptanceIsDurableWithoutCreatingContactsUntilClaimed()throws Exception{long before=count("SELECT count(*) FROM public.mop_customer_contact");Job accepted=accept(row("pending"));var other=new PostgresContactImportRepository(pool,new PostgresPlatformRepository(pool,mapper));Job read=other.get(admin(),accepted.id());assertEquals(accepted,read);assertEquals(State.PENDING,read.state().state());assertEquals(1,read.version());assertTrue(read.results().isEmpty());assertEquals(before,count("SELECT count(*) FROM public.mop_customer_contact"));}
    @Test void successfulWholeBatchLinksImmutableFirstRevisionsAndKeepsInputOrder(){var a=row("same");var b=row("other");Job job=accept(a,b,a);assertTrue(imports.process(claim(job)));Job done=imports.get(admin(),job.id());assertEquals(State.SUCCEEDED,done.state().state());assertEquals(3,done.state().completedRows());assertEquals(3,done.version());assertEquals(3,done.results().stream().map(ResultLink::contactId).distinct().count());assertEquals(List.of(a,b,a),done.results().stream().map(r->contacts.get(admin(),r.contactId()).facts()).toList());assertTrue(done.results().stream().allMatch(r->r.contactVersion()==1));assertThrows(UnsupportedOperationException.class,()->done.results().clear());}
    @Test void tenantAdminAllowedButOtherCreatorsAndTenantsCannotReadJob(){Job job=accept(access(tadmin,A),List.of(row("tenant_admin")));assertEquals(tadmin,imports.get(access(tadmin,A),job.id()).createdBy());assertEquals(404,assertThrows(DomainException.class,()->imports.get(access(admin,A),job.id())).status);assertEquals(404,assertThrows(DomainException.class,()->imports.get(access(admin,B),job.id())).status);}
    @Test void actualRolesAndStaleVersionsRejectedWithoutNewJob()throws Exception{long before=count("SELECT count(*) FROM public.mop_contact_import_job");for(String user:List.of(msp,viewer))assertEquals(403,assertThrows(DomainException.class,()->accept(access(user,A),List.of(row("denied")))).status);Access a=admin();Access stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->accept(stale,List.of(row("stale")))).status);assertEquals(before,count("SELECT count(*) FROM public.mop_contact_import_job"));}
    @Test void acceptanceRequiresIdempotentCommandAndValidRows(){assertThrows(IllegalStateException.class,()->imports.accept(admin(),List.of(row("unprotected"))));for(List<CustomerContact> rows:Arrays.asList(null,List.<CustomerContact>of(),Arrays.asList(row("invalid"),null),Collections.nCopies(101,row("too_many"))))assertThrows(DomainException.class,()->command(admin(),"POST /integration/contact-import-invalid",UUID.randomUUID().toString(),"a".repeat(64),()->imports.accept(admin(),rows)));}
    @Test void originalAcceptedReceiptDoesNotBecomeCurrentSuccessOrCreateAnotherJob(){Access a=admin();var rows=List.of(row("replay"));String route="POST /integration/contact-import-replay",key=UUID.randomUUID().toString(),hash=ContactImportPayloadCodec.hash(ContactImportPayloadCodec.encode(rows));Object original=command(a,route,key,hash,()->imports.accept(a,rows));Job job=(Job)original;owned.add(job.id());assertTrue(imports.process(claim(job)));Object replay=command(a,route,key,hash,()->{throw new AssertionError("No duplicate import acceptance");});assertEquals(json(original),json(replay));assertEquals(State.SUCCEEDED,imports.get(a,job.id()).state().state());assertEquals(409,assertThrows(DomainException.class,()->command(a,route,key,"b".repeat(64),()->null)).status);}
    @Test void twoIndependentWorkersCanClaimTargetOnlyOnce()throws Exception{Job job=accept(row("claim"));ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Optional<Claim>>> futures=new ArrayList<>();for(int i=0;i<2;i++){String worker="parallel-"+i;futures.add(executor.submit(()->{start.await();return imports.claim(job.id(),worker,Duration.ofSeconds(30));}));}start.countDown();List<Claim> claims=new ArrayList<>();for(var future:futures)future.get(20,TimeUnit.SECONDS).ifPresent(claims::add);assertEquals(1,claims.size());assertTrue(imports.process(claims.get(0)));}finally{executor.shutdownNow();}}
    @Test void concurrentSameClaimProcessingCreatesOneBatchOnly()throws Exception{Job job=accept(row("processA"),row("processB"));Claim claim=claim(job);ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(executor.submit(()->{start.await();return imports.process(claim);}));start.countDown();int successes=0;for(var future:futures)if(future.get(20,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(2,imports.get(admin(),job.id()).results().size());assertEquals(1,count("SELECT count(*) FROM public.mop_audit WHERE payload->>'resource_id'='"+job.id()+"' AND payload->>'action'='customer_contact_import.complete'"));}finally{executor.shutdownNow();}}
    @Test void expiredLeaseReconstructionAndOldFenceNeverDuplicatesRows()throws Exception{Job job=accept(row("expired"));Claim old=imports.claim(job.id(),"old-worker",Duration.ofMillis(30)).orElseThrow();Thread.sleep(60);assertFalse(imports.process(old));var reconstructed=new PostgresContactImportRepository(pool,new PostgresPlatformRepository(pool,mapper));Claim current=reconstructed.claim(job.id(),"new-worker",Duration.ofSeconds(30)).orElseThrow();assertEquals(2,current.fencingToken());assertFalse(reconstructed.process(old));assertTrue(reconstructed.process(current));assertEquals(1,reconstructed.get(admin(),job.id()).results().size());assertFalse(reconstructed.process(current));}
    @Test void wrongOwnerAndFenceLeaveClaimAndContactsUnchanged()throws Exception{Job job=accept(row("fence"));Claim current=claim(job);long before=count("SELECT count(*) FROM public.mop_customer_contact");assertFalse(imports.process(new Claim(job.id(),"wrong-worker",current.fencingToken())));assertFalse(imports.process(new Claim(job.id(),current.worker(),current.fencingToken()+1)));assertEquals(before,count("SELECT count(*) FROM public.mop_customer_contact"));assertEquals(State.LEASED,imports.get(admin(),job.id()).state().state());assertTrue(imports.process(current));}
    String seeded(String actor,String tenant,long permission,byte[] payload)throws Exception{String id=UUID.randomUUID().toString();try(var c=pool.getConnection();var s=c.prepareStatement("INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id) VALUES (?::uuid,?::uuid,?::uuid,?,1,?,?)")){s.setString(1,id);s.setString(2,tenant);s.setString(3,actor);s.setLong(4,permission);s.setBytes(5,payload);s.setString(6,UUID.randomUUID().toString());s.executeUpdate();}owned.add(id);return id;}
    @Test void invalidDurablePayloadFailsWithoutContactMutation()throws Exception{long before=count("SELECT count(*) FROM public.mop_customer_contact");String id=seeded(admin,B,admin().permissionVersion(),"{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));assertTrue(imports.process(imports.claim(id,"invalid-payload",Duration.ofSeconds(30)).orElseThrow()));var job=imports.get(admin(),id);assertEquals(State.FAILED,job.state().state());assertEquals(Failure.PAYLOAD_INVALID,job.state().error());assertEquals(before,count("SELECT count(*) FROM public.mop_customer_contact"));}
    @Test void capturedStaleVersionAndUnauthorizedActorFailAgainstCurrentRealMembershipWithoutRoleMutation()throws Exception{byte[] payload=ContactImportPayloadCodec.encode(List.of(row("authorization")));long before=count("SELECT count(*) FROM public.mop_customer_contact");String stale=seeded(admin,B,admin().permissionVersion()+1,payload),denied=seeded(msp,A,access(msp,A).permissionVersion(),"{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));for(String id:List.of(stale,denied)){assertTrue(imports.process(imports.claim(id,"auth-check",Duration.ofSeconds(30)).orElseThrow()));assertEquals("FAILED|AUTHORIZATION_REVOKED",scalar("SELECT state||'|'||error_code FROM public.mop_contact_import_job WHERE id='"+id+"'"));}assertEquals(before,count("SELECT count(*) FROM public.mop_customer_contact"));}
    @Test void successfulReadsDoNotAppendAuditAndDoNotExposePayloadBytes()throws Exception{Job job=accept(row("read"));long before=count("SELECT count(*) FROM public.mop_audit");var read=imports.get(admin(),job.id());assertFalse(json(read).has("payload_bytes"));assertEquals(before,count("SELECT count(*) FROM public.mop_audit"));}
    @Test void maximumHundredRowsCompleteAtomically(){List<CustomerContact> rows=new ArrayList<>();for(int i=0;i<100;i++)rows.add(row("hundred_"+i));Job job=accept(admin(),rows);assertTrue(imports.process(claim(job)));assertEquals(100,imports.get(admin(),job.id()).results().size());}
    static Object reflect(java.lang.reflect.Method method,Object target,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(java.lang.reflect.InvocationTargetException failure){throw failure.getCause();}}
    @Test void realSqlFailureRollsBackWholeBatchThenExplicitBackoffRetriesOnce()throws Exception{
        Job job=accept(row("retryA"),row("retryB"));Claim lease=claim(job);long before=count("SELECT count(*) FROM public.mop_customer_contact"),audit=count("SELECT count(*) FROM public.mop_audit WHERE payload->>'resource_type'='customer_contact'");
        var inserts=new java.util.concurrent.atomic.AtomicInteger();javax.sql.DataSource injected=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(proxy,method,args)->{Object result=reflect(method,pool,args);if(result instanceof Connection real)return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql&&sql.startsWith("INSERT INTO public.mop_customer_contact(")&&inserts.incrementAndGet()==2){try(var statement=real.createStatement()){statement.execute("SELECT 1/0");}}return reflect(cm,real,ca);});return result;});
        var faulty=new PostgresContactImportRepository(injected,new PostgresPlatformRepository(injected,mapper));assertFalse(faulty.process(lease));Job waiting=imports.get(admin(),job.id());assertEquals(State.PENDING,waiting.state().state());assertEquals(Failure.UPSTREAM_UNAVAILABLE,waiting.state().error());assertEquals(1,waiting.state().attempts());assertTrue(waiting.results().isEmpty());assertEquals(before,count("SELECT count(*) FROM public.mop_customer_contact"));assertEquals(audit,count("SELECT count(*) FROM public.mop_audit WHERE payload->>'resource_type'='customer_contact'"));assertEquals(0,count("SELECT count(*) FROM public.mop_idempotency WHERE route='WORKER /contact-imports/"+job.id()+"'"));assertTrue(imports.claim(job.id(),"early-retry",Duration.ofSeconds(30)).isEmpty());
        long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(!scalar("SELECT (next_at<=clock_timestamp())::text FROM public.mop_contact_import_job WHERE id='"+job.id()+"'").equals("true")){assertTrue(System.nanoTime()<until);Thread.sleep(20);}Claim next=imports.claim(job.id(),"real-retry",Duration.ofSeconds(30)).orElseThrow();assertEquals(2,next.fencingToken());assertTrue(imports.process(next));assertEquals(2,imports.get(admin(),job.id()).results().size());assertEquals(before+2,count("SELECT count(*) FROM public.mop_customer_contact"));
    }
    static Map<String,String> identities()throws Exception{Map<String,String> result=new LinkedHashMap<>();try(var c=pool.getConnection();var s=c.createStatement()){for(String table:List.of("mop_user","mop_membership"))try(var r=s.executeQuery("SELECT encode(sha256(convert_to(COALESCE(string_agg(to_jsonb(t)::text,E'\\n' ORDER BY to_jsonb(t)::text),''),'UTF8')),'hex') FROM public."+table+" t")){assertTrue(r.next());result.put(table,r.getString(1));}}return result;}
    @Test void importAcceptanceProcessingAndArchivalDoNotChangeIdentityBindings()throws Exception{var before=identities();Job job=accept(row("identity"));assertTrue(imports.process(claim(job)));assertEquals(before,identities());}
    @Test void failedAcceptanceCommandDoesNotLeaveDurableJobOrReceipt()throws Exception{Access a=admin();long before=count("SELECT count(*) FROM public.mop_contact_import_job"),receipts=count("SELECT count(*) FROM public.mop_idempotency"),audits=count("SELECT count(*) FROM public.mop_audit");assertThrows(IllegalStateException.class,()->command(a,"POST /integration/import-rollback",UUID.randomUUID().toString(),"a".repeat(64),()->{imports.accept(a,List.of(row("accept-rollback")));throw new IllegalStateException("Controlled downstream acceptance failure");}));assertEquals(before,count("SELECT count(*) FROM public.mop_contact_import_job"));assertEquals(receipts,count("SELECT count(*) FROM public.mop_idempotency"));assertEquals(audits,count("SELECT count(*) FROM public.mop_audit"));}

    @Test void nextClaimScansOnlyDedicatedQueueAndLeasedRowsAreSkipped()throws Exception{Assumptions.assumeTrue(count("SELECT count(*) FROM public.mop_contact_import_job WHERE state IN ('PENDING','LEASED')")==0,"Do not claim unrelated pending jobs during test");Job one=accept(row("scanA")),two=accept(row("scanB"));Set<String> expected=Set.of(one.id(),two.id());Claim first=imports.claimNext("scan-one",Duration.ofSeconds(30)).orElseThrow(),second=imports.claimNext("scan-two",Duration.ofSeconds(30)).orElseThrow();assertEquals(expected,Set.of(first.jobId(),second.jobId()));assertTrue(imports.claimNext("scan-three",Duration.ofSeconds(30)).isEmpty());assertTrue(imports.process(first));assertTrue(imports.process(second));}

    @Test void ownCreatorTenantKeysetPagesStayBoundedUniqueAndReadonly()throws Exception{
        Access a=access(tadmin,A);Set<String> expected=new HashSet<>();for(int i=0;i<17;i++)expected.add(accept(a,List.of(row("page_"+i))).id());long audit=count("SELECT count(*) FROM public.mop_audit");
        var first=imports.list(a,15,null,null);assertEquals(15,first.size());var last=first.get(14);var second=imports.list(a,15,last.createdAt(),last.id());Set<String> seen=new HashSet<>();for(var j:first){assertTrue(seen.add(j.id()));assertEquals(A,j.tenantId());assertEquals(tadmin,j.createdBy());}for(var j:second)assertTrue(seen.add(j.id()));assertTrue(seen.containsAll(expected));assertThrows(UnsupportedOperationException.class,()->first.clear());assertEquals(audit,count("SELECT count(*) FROM public.mop_audit"));
        for(var other:imports.list(access(admin,A),101,null,null))assertFalse(expected.contains(other.id()));for(var other:imports.list(access(admin,B),101,null,null))assertFalse(expected.contains(other.id()));
    }
    @Test void listRechecksAuthorizationAndRejectsUnboundedOrUnpairedCursors(){
        for(int limit:List.of(0,102,-1))assertEquals(400,assertThrows(DomainException.class,()->imports.list(admin(),limit,null,null)).status);
        assertEquals(400,assertThrows(DomainException.class,()->imports.list(admin(),15,Instant.now(),null)).status);assertEquals(400,assertThrows(DomainException.class,()->imports.list(admin(),15,null,UUID.randomUUID().toString())).status);
        for(String user:List.of(msp,viewer))assertEquals(403,assertThrows(DomainException.class,()->imports.list(access(user,A),15,null,null)).status);var a=admin();assertEquals(401,assertThrows(DomainException.class,()->imports.list(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId()),15,null,null)).status);
    }
}
